// buoy_map_publisher: publishes the true buoy map once (M2.7, D7 a). Only I/O;
// parsing and checks are asv_sim::parse_buoy_map() (buoy_map.hpp).
//   out: /asv/ground_truth/buoys   asv_msgs/LandmarkArray, latched: QoS
//        transient_local + reliable, depth 1, so a node that subscribes later
//        (fake detector, evaluation) still gets it.
// The map is read from config/buoys_gt.yaml in the package share directory
// (generated by tools/make_buoy_map.py). It is published once, at the first
// nonzero simulation time, so the header stamp is a simulation time.
// Started by sim.launch.py. Alone:
//      ros2 run asv_sim buoy_map_publisher --ros-args -p use_sim_time:=true
#include <chrono>
#include <memory>
#include <string>

#include "ament_index_cpp/get_package_share_directory.hpp"
#include "asv_msgs/msg/buoy_colour.hpp"
#include "asv_msgs/msg/landmark_array.hpp"
#include "rclcpp/rclcpp.hpp"
#include "yaml-cpp/yaml.h"

#include "asv_sim/buoy_map.hpp"

namespace
{
using asv_msgs::msg::BuoyColour;
static_assert(BuoyColour::RED == 1 && BuoyColour::GREEN == 2 && BuoyColour::YELLOW == 3 &&
  BuoyColour::BLACK == 4, "asv_sim::colour_code() must match asv_msgs/BuoyColour");
}  // namespace

class BuoyMapPublisher : public rclcpp::Node
{
public:
  BuoyMapPublisher()
  : Node("buoy_map_publisher")
  {
    const std::string path =
      ament_index_cpp::get_package_share_directory("asv_sim") + "/config/buoys_gt.yaml";
    map_ = asv_sim::parse_buoy_map(YAML::LoadFile(path));
    RCLCPP_INFO(get_logger(), "%zu objects from %s", map_.buoys.size(), path.c_str());

    pub_ = create_publisher<asv_msgs::msg::LandmarkArray>(
      "/asv/ground_truth/buoys", rclcpp::QoS(1).reliable().transient_local());
    // ROS clock (design.md section 3): waits for the first /clock message.
    timer_ = rclcpp::create_timer(
      this, get_clock(), std::chrono::milliseconds(100), [this]() {publish_once();});
  }

private:
  void publish_once()
  {
    const rclcpp::Time now = get_clock()->now();
    if (now.nanoseconds() == 0) {
      return;  // no /clock yet
    }
    asv_msgs::msg::LandmarkArray msg;
    msg.header.stamp = now;
    msg.header.frame_id = map_.frame_id;
    for (const auto & b : map_.buoys) {
      asv_msgs::msg::Landmark l;
      l.id = b.id;
      l.name = b.name;
      l.colour.value = asv_sim::colour_code(b.colour);
      l.model = b.cls;
      l.radius = b.radius;
      l.x = b.x;
      l.y = b.y;
      // covariance all zero, sightings 0: exact, never observed (Landmark.msg)
      l.confirmed = true;
      msg.landmarks.push_back(l);
    }
    pub_->publish(msg);
    RCLCPP_INFO(get_logger(), "published %zu landmarks at t = %.3f s",
      msg.landmarks.size(), now.seconds());
    timer_->cancel();
  }

  asv_sim::BuoyMap map_;
  rclcpp::Publisher<asv_msgs::msg::LandmarkArray>::SharedPtr pub_;
  rclcpp::TimerBase::SharedPtr timer_;
};

int main(int argc, char ** argv)
{
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<BuoyMapPublisher>());
  rclcpp::shutdown();
  return 0;
}
